A = []

A.append(dict(
slug='pre-ipo-funding-investor-sebelum-ipo',
seo_title='Pre-IPO Funding: Investor Sebelum Perusahaan IPO',
title='Pre-IPO Funding: Kapan Perusahaan Cocok Mencari Investor Sebelum IPO',
description='Pendanaan pre-IPO membawa investor masuk sebelum listing. Ini kapan cocok, apa yang dilihat investor, dampaknya ke harga IPO, dan hal yang perlu dirapikan lebih dulu.',
keyword='pre-ipo funding', category='Investor & IPO', minutes=7,
cta={'href':'/konsultan-persiapan-ipo/','label':'Konsultan Persiapan IPO'},
wa='Halo FA Indonesia, saya ingin menjajaki pendanaan pre-IPO untuk perusahaan saya.',
sources=[['https://market.bisnis.com/read/20250716/7/1893646/penjamin-emisi-efek-wajib-lakukan-uji-tuntas-calon-emiten-cek-aturannya','Bisnis.com, POJK 13/2025: penjamin emisi wajib uji tuntas calon emiten'],['https://www.ojk.go.id/id/regulasi/Pages/POJK-40-Tahun-2025-Penggunaan-Dana-Hasil-Penawaran-Umum.aspx','OJK, POJK 40/2025 tentang Penggunaan Dana Hasil Penawaran Umum']],
related=['checklist-persiapan-ipo','usaha-keluarga-siap-ipo-langkah-awal','syarat-ipo-papan-utama-pengembangan-bei-2026','biaya-ipo-di-bei-rincian'],
body_html='''<p>Pendanaan pre-IPO adalah masuknya investor ke perusahaan sebelum perusahaan melantai di bursa. Bagi pemilik, ini bisa menjadi jembatan: tambahan modal untuk mematangkan bisnis dan tata kelola, sekaligus sinyal kepada pasar bahwa ada pihak berpengalaman yang percaya pada perusahaan. Tetapi tidak semua perusahaan cocok, dan syaratnya sering lebih berat dari yang dibayangkan.</p>
<h2>Kapan Pendanaan Pre-IPO Masuk Akal</h2>
<ul><li>Perusahaan butuh modal untuk ekspansi atau memperkuat struktur permodalan, tetapi belum siap memenuhi syarat listing dalam waktu dekat.</li>
<li>Pemilik ingin investor strategis yang membantu tata kelola, jaringan, atau pasar.</li>
<li>Pemilik ingin sebagian pemegang saham lama keluar secara terukur sebelum IPO.</li>
<li>Struktur dan laporan keuangan sudah cukup rapi untuk dilihat investor yang berpengalaman.</li></ul>
<h2>Yang Dilihat Investor Pre-IPO</h2>
''' + T(['Area','Pertanyaan investor'],[
 ['Bisnis','Seberapa besar pasar, apa keunggulan perusahaan, seberapa tergantung pada beberapa pelanggan atau pemilik'],
 ['Keuangan','Laporan audited 2 sampai 3 tahun, kualitas laba, arus kas, dan proyeksi'],
 ['Tata kelola','Direksi dan komisaris, komite audit, pengendalian internal, transaksi afiliasi'],
 ['Struktur','Siapa memiliki apa, apakah ada PT yang perlu digabung atau dirapikan sebelum IPO'],
 ['Jalur keluar','Rencana dan waktu IPO, lock-up, dan hak investor bila IPO tertunda'],
 ['Valuasi','Dasar harga masuk dan hubungannya dengan harga IPO nantinya']]) + '''
<h2>Dampak ke Harga dan Struktur IPO</h2>
<p>Harga masuk investor pre-IPO biasanya lebih rendah dari harga IPO yang ditargetkan, sehingga mereka mendapat ruang imbal hasil. Akibatnya pemilik lama mengalami dilusi lebih awal. Karena itu pemilik perlu menghitung berapa kepemilikan yang ingin dipertahankan setelah IPO, bukan hanya berapa dana yang masuk sekarang. Investor juga hampir selalu meminta hak tertentu, misalnya informasi, persetujuan atas keputusan besar, dan perlindungan bila IPO tidak terjadi dalam jangka waktu yang disepakati. Hak seperti ini perlu dipikirkan bersama penasihat hukum, karena kondisi tertentu bisa tidak sejalan dengan struktur perusahaan terbuka.</p>
<h2>Regulasi yang Perlu Diperhatikan</h2>
<ul><li>OJK mengatur kewajiban penjamin emisi efek melakukan uji tuntas atas calon emiten sebelum pendaftaran (POJK 13/2025). Artinya data perusahaan akan diperiksa lebih ketat, termasuk riwayat pendanaan pre-IPO.</li>
<li>Penggunaan dana hasil penawaran umum diatur POJK 40/2025, antara lain penempatan pada rekening khusus. Rencana penggunaan dana di prospektus perlu realistis sejak awal.</li>
<li>BEI mengubah syarat pencatatan efektif 9 Oktober 2026. Bacaan terkait ada di <a href="/artikel/syarat-ipo-papan-utama-pengembangan-bei-2026/">artikel syarat IPO papan utama dan pengembangan</a>.</li></ul>
<h2>Yang Perlu Dirapikan Sebelum Mendekati Investor</h2>
<ol><li>Laporan keuangan yang diaudit dan konsisten dengan SPT.</li>
<li>Pemisahan transaksi pemilik dengan perusahaan.</li>
<li>Struktur grup yang bisa dijelaskan dalam satu halaman.</li>
<li>Data room yang siap, termasuk kontrak besar dan perizinan.</li>
<li>Rencana penggunaan dana yang bisa dipertanggungjawabkan.</li>
<li>Peran CFO atau fungsi keuangan yang cukup kuat, atau dukungan <a href="/cfo-paruh-waktu/">CFO paruh waktu</a> untuk masa persiapan.</li></ol>
<h2>Bagaimana FA Indonesia Membantu</h2>
<p>Tim FA Indonesia membantu menilai apakah pendanaan pre-IPO cocok untuk perusahaan Anda, merapikan laporan, menyiapkan data room, dan menyusun materi untuk investor. Pengalaman kami mencakup pendanaan investor hingga US$3 juta untuk grup rumah sakit. Ini bukan jaminan hasil; keputusan akhir ada pada investor dan otoritas. Lihat <a href="/konsultan-persiapan-ipo/">layanan persiapan IPO</a> dan <a href="/artikel/checklist-persiapan-ipo/">checklist persiapan IPO</a>.</p>''',
faq=[['Apakah pendanaan pre-IPO wajib sebelum IPO?','Tidak. Banyak perusahaan IPO tanpa investor pre-IPO. Pendanaan ini pilihan strategis, bukan syarat.'],
['Berapa lama pre-IPO sampai IPO?','Tidak ada patokan tunggal. Biasanya sejalan dengan kesiapan laporan audited, tata kelola, dan kondisi pasar.'],
['Apakah pre-IPO sama dengan private placement?','Pre-IPO adalah tahap waktunya, yaitu sebelum IPO. Private placement adalah caranya, yaitu penerbitan saham kepada investor terpilih. Pre-IPO sering dilakukan lewat private placement.'],
['Bagaimana harga ditentukan?','Biasanya lewat valuasi dan negosiasi, dengan acuan prospek IPO. Valuasi lengkap membantu agar angka bisa dipertahankan di depan investor.']]))

A.append(dict(
slug='cash-flow-forecast-13-minggu-perusahaan-menengah',
seo_title='Cash Flow Forecast 13 Minggu untuk Perusahaan Menengah',
title='Cash Flow Forecast 13 Minggu: Cara Membuat dan Memakainya Memimpin Perusahaan',
description='Forecast kas 13 minggu memberi pemilik gambaran jelas kapan kas mepet. Ini format, sumber data, contoh ilustrasi, dan cara memakainya untuk keputusan pembayaran dan kredit.',
keyword='cash flow forecast', category='CFO & Tata Kelola', minutes=6,
cta={'href':'/cfo-paruh-waktu/','label':'CFO Paruh Waktu'},
wa='Halo FA Indonesia, saya ingin membuat forecast arus kas 13 minggu untuk perusahaan saya.',
sources=[['https://web.iaiglobal.or.id/','Ikatan Akuntan Indonesia, SAK Online']],
related=['cfo-paruh-waktu-untuk-perusahaan-menengah','rencana-kerja-3-bulan-sebelum-mengajukan-kredit','kmk-vs-kredit-investasi','dscr-adalah-cara-menghitung-kredit-bank'],
body_html='''<p>Laba bagus tidak menjamin kas cukup. Perusahaan yang sedang tumbuh, apalagi kontraktor atau distributor dengan piutang panjang, sering kehabisan kas justru saat penjualannya naik. Forecast kas 13 minggu adalah alat sederhana yang menjawab satu pertanyaan: dalam tiga bulan ke depan, minggu mana kas kita menipis, dan apa yang bisa dilakukan sekarang?</p>
<h2>Kenapa 13 Minggu</h2>
<p>Satu kuartal cukup pendek untuk akurat, tetapi cukup panjang untuk bertindak, misalnya menegosiasikan termin pembayaran, menunda belanja modal, atau meminta bank menyesuaikan jadwal. Forecast ini diperbarui setiap minggu dan membandingkan prediksi dengan kenyataan.</p>
<h2>Format Dasarnya</h2>
''' + T(['Baris','Isi','Sumber data'],[
 ['Saldo kas awal','Saldo bank dan kas minggu itu','Rekening koran'],
 ['Penerimaan','Pelunasan piutang per minggu, penjualan tunai, penerimaan lain','Daftar umur piutang, jadwal penagihan'],
 ['Pembayaran operasional','Pemasok, gaji, sewa, listrik, biaya rutin','Daftar utang dan jadwal pembayaran'],
 ['Pajak dan pungutan','PPN, PPh 21, PPh 23, PPh 25, BPJS, sesuai tanggal jatuh tempo','Kalender pajak'],
 ['Cicilan dan bunga','Jadwal kredit bank, leasing, utang lain','Perjanjian kredit'],
 ['Belanja modal','Pembelian aset, uang muka proyek','Rencana investasi'],
 ['Saldo kas akhir','Hasil akhir tiap minggu dan minimum yang aman','Hitungan']]) + '''
<h2>Contoh Ilustrasi</h2>
<p>Angka ini ilustrasi. Perusahaan distribusi punya saldo kas awal Rp800 juta. Dalam 13 minggu, penerimaan terjadwal Rp6 miliar, tetapi pembayaran ke pemasok dan gaji Rp4,8 miliar, pajak Rp900 juta, dan cicilan Rp600 juta. Saldo akhir tampak positif Rp500 juta. Namun bila di minggu ke-5 pemasok besar jatuh tempo Rp1,5 miliar sedangkan piutang baru tertagih di minggu ke-8, saldo di minggu ke-6 bisa negatif. Hanya forecast mingguan yang memperlihatkan lubang seperti ini, laporan bulanan tidak.</p>
<h2>Cara Memakainya</h2>
<ul><li><b>Tentukan batas kas minimum.</b> Misalnya setara kebutuhan operasional dua minggu. Tandai minggu yang menembus batas.</li>
<li><b>Dahulukan tindakan murah.</b> Percepat penagihan, minta termin pembayaran pemasok, atau atur ulang jadwal pembelian sebelum mencari pinjaman.</li>
<li><b>Bila perlu pembiayaan, ajukan lebih awal.</b> Bank lebih mudah dihadapi saat kas masih sehat. Pembahasan jenis kredit ada di <a href="/artikel/kmk-vs-kredit-investasi/">artikel KMK dan kredit investasi</a>.</li>
<li><b>Bandingkan prediksi dan kenyataan tiap minggu.</b> Selisih berulang menunjukkan asumsi yang perlu diperbaiki, misalnya pelanggan tertentu selalu membayar terlambat.</li></ul>
<h2>Kesalahan yang Umum</h2>
<ul><li>Memakai tanggal faktur, bukan tanggal perkiraan pembayaran pelanggan.</li>
<li>Melupakan pajak dan cicilan yang jatuh tempo bersamaan.</li>
<li>Tidak ada pemilik tunggal yang memperbarui tiap minggu.</li>
<li>Terlalu rinci sehingga tidak pernah diperbarui. Lebih baik sederhana dan rutin.</li></ul>
<h2>Bagaimana FA Indonesia Membantu</h2>
<p>Tim FA Indonesia membantu membangun template forecast, menyambungkannya ke data piutang dan utang, dan menjalankan rutinitas mingguan lewat layanan <a href="/cfo-paruh-waktu/">CFO paruh waktu</a>. Bila tujuan Anda menyiapkan pengajuan kredit, lihat juga <a href="/artikel/rencana-kerja-3-bulan-sebelum-mengajukan-kredit/">rencana kerja 3 bulan sebelum mengajukan kredit</a>.</p>''',
faq=[['Apakah forecast 13 minggu sama dengan anggaran?','Tidak. Anggaran bersifat tahunan dan berbasis laba. Forecast kas berbasis uang masuk dan keluar nyata per minggu, dan diperbarui rutin.'],
['Perlu software khusus?','Tidak. Spreadsheet yang rapi sudah cukup untuk perusahaan menengah. Yang penting disiplin memperbarui tiap minggu.'],
['Siapa yang sebaiknya memegang?','Orang keuangan yang punya akses ke data piutang, utang, dan bank, dengan pemilik atau direksi yang membaca hasilnya tiap minggu.'],
['Apakah bank menerima forecast ini?','Bank biasanya menyambut baik, terutama untuk kredit modal kerja, karena menunjukkan debitur memahami siklus kasnya. Format laporannya bisa disesuaikan.']]))

A.append(dict(
slug='utang-pemegang-saham-dijadikan-modal-atau-tetap-pinjaman',
seo_title='Utang Pemegang Saham: Jadikan Modal atau Tetap Pinjaman',
title='Utang Pemegang Saham: Dijadikan Modal Disetor atau Tetap Berupa Pinjaman',
description='Pemilik sering menyuntik dana ke PT lewat pinjaman. Ini perbedaan pinjaman dan setoran modal, dampak ke bank, batas rasio utang terhadap modal 4:1, dan cara memutuskannya.',
keyword='utang pemegang saham', category='Laporan Keuangan', minutes=7,
cta={'href':'/jasa-penyusunan-laporan-keuangan/','label':'Jasa Penyusunan Laporan Keuangan'},
wa='Halo FA Indonesia, PT saya punya utang ke pemegang saham. Apakah lebih baik dijadikan modal?',
sources=[['https://news.ddtc.co.id/berita/nasional/1819712/perusahaan-harus-tahu-aturan-der-biar-biaya-bunga-tetap-jadi-pengurang','DDTCNews, aturan DER agar biaya bunga tetap menjadi pengurang'],['https://web.iaiglobal.or.id/assets/files/file_publikasi/Achmad Amin_DJP_PPT_DER_21092015.pdf','DJP, materi PMK 169/PMK.010/2015 tentang DER']],
related=['pisahkan-uang-pribadi-dan-perusahaan','dokumen-transfer-pricing-master-file-local-file','rasio-keuangan-yang-dilihat-bank','laporan-keuangan-konsolidasian-grup-usaha-keluarga'],
body_html='''<p>Di banyak PT milik keluarga, dana dari pemilik masuk lewat rekening perusahaan tanpa banyak dokumen: untuk menutup kas, membeli aset, atau membayar gaji. Di pembukuan, dana itu menjadi "utang pemegang saham". Bertahun-tahun kemudian saldonya besar, tidak jelas statusnya, dan mulai dipertanyakan bank, auditor, atau pemeriksa pajak. Pertanyaannya: sebaiknya dijadikan modal disetor atau tetap dicatat sebagai pinjaman?</p>
<h2>Perbedaan Mendasar</h2>
''' + T(['Aspek','Tetap sebagai pinjaman','Dijadikan modal disetor'],[
 ['Hak pemilik','Bisa ditagih kembali sesuai perjanjian','Tidak bisa ditarik; kembali lewat dividen atau pengurangan modal'],
 ['Bunga','Bisa berbunga bila diperjanjikan','Tidak ada bunga'],
 ['Rasio utang terhadap modal (DER)','Menaikkan utang','Menaikkan ekuitas, memperbaiki rasio'],
 ['Pandangan bank','Sering dianggap setara ekuitas bila disubordinasi','Ekuitas riil'],
 ['Dokumen','Perjanjian pinjaman, jadwal, bunga bila ada','Akta perubahan modal dan pencatatan pada instansi terkait'],
 ['Fleksibilitas','Lebih fleksibel','Lebih permanen']]) + '''
<h2>Yang Dilihat Bank</h2>
<p>Bank menghitung rasio seperti DER dan kecukupan ekuitas. Utang pemegang saham yang besar membuat rasio terlihat buruk bila dianggap utang biasa. Sebagian bank menerima pinjaman pemegang saham sebagai bagian dari ekuitas bila ada perjanjian subordinasi, yaitu pemilik berjanji tidak menarik dana sebelum kredit bank lunas. Praktiknya berbeda tiap bank, jadi tanyakan sebelum memutuskan. Kualitas catatan ini juga memengaruhi persepsi bank atas laporan keuangan secara keseluruhan, seperti dibahas di <a href="/artikel/rasio-keuangan-yang-dilihat-bank/">artikel rasio keuangan yang dilihat bank</a>.</p>
<h2>Sisi Pajak yang Perlu Diwaspadai</h2>
<ul><li><b>Batas rasio utang terhadap modal.</b> PMK 169/PMK.010/2015 menetapkan rasio utang terhadap modal paling tinggi 4:1 untuk keperluan penghitungan PPh badan. Bila rasio melewati batas, biaya pinjaman yang dapat dikurangkan hanya sebesar porsi yang sesuai rasio 4:1. Ada pengecualian untuk jenis wajib pajak tertentu seperti bank dan lembaga pembiayaan.</li>
<li><b>Bunga pinjaman afiliasi.</b> Pinjaman dari pemegang saham termasuk transaksi afiliasi sehingga tingkat bunganya perlu wajar. Lihat <a href="/artikel/dokumen-transfer-pricing-master-file-local-file/">artikel dokumen transfer pricing</a>.</li>
<li><b>Pinjaman tanpa bunga.</b> Pencatatan dan perlakuan pajaknya perlu dipastikan bersama konsultan pajak.</li>
<li><b>Saldo lama yang tidak jelas.</b> Saldo yang sudah bertahun-tahun tanpa perjanjian dan tanpa pergerakan sering ditanyakan auditor dan pemeriksa pajak.</li></ul>
<h2>Cara Memutuskan</h2>
<ol><li>Rekonsiliasi saldo: apa saja yang membentuk saldo utang pemegang saham, dan apakah semuanya benar-benar dana masuk dari pemilik.</li>
<li>Tentukan tujuan: memperbaiki rasio untuk bank, menyiapkan investor, atau merapikan sebelum audit.</li>
<li>Pertimbangkan kebutuhan pemilik atas dana itu. Setelah dijadikan modal, dana tidak mudah ditarik.</li>
<li>Bila dijadikan modal, siapkan RUPS, akta perubahan, dan pencatatan yang sesuai ketentuan. Bila tetap pinjaman, buat perjanjian tertulis, tentukan bunga dan jadwal.</li>
<li>Konsultasikan dengan notaris dan konsultan pajak untuk dokumen dan dampak fiskalnya.</li></ol>
<h2>Bagaimana FA Indonesia Membantu</h2>
<p>Tim FA Indonesia membantu rekonsiliasi saldo, menghitung dampak ke rasio keuangan dan kovenan bank, dan merapikan penyajiannya di laporan keuangan. Bila usaha Anda terdiri dari beberapa PT, lihat juga <a href="/artikel/laporan-keuangan-konsolidasian-grup-usaha-keluarga/">laporan keuangan konsolidasian grup usaha keluarga</a> dan <a href="/jasa-penyusunan-laporan-keuangan/">layanan penyusunan laporan keuangan</a>. Keputusan hukum dan pajak finalnya tetap sebaiknya melibatkan notaris dan konsultan pajak berizin.</p>''',
faq=[['Apakah utang pemegang saham bisa dijadikan modal tanpa pajak?','Perlakuan pajaknya bergantung pada fakta dan cara pelaksanaannya. Pastikan dengan konsultan pajak sebelum melakukan konversi.'],
['Apakah bank menganggap utang pemegang saham sebagai ekuitas?','Sebagian bank bisa, terutama bila ada perjanjian subordinasi. Kebijakannya berbeda per bank dan per produk kredit.'],
['Bolehkah pemilik menarik kembali pinjamannya kapan saja?','Sesuai perjanjian dan kondisi kas perusahaan. Bila ada kovenan bank, penarikan bisa dilarang atau dibatasi.'],
['Bagaimana bila tidak ada perjanjian tertulis?','Sebaiknya dibuat perjanjian yang menjelaskan saldo, bunga bila ada, dan jadwal. Pencatatan tanpa dokumen mudah dipertanyakan auditor dan pemeriksa pajak.']]))
